        return None

    def find_first_pair(obj):
        p = to_pair(obj)
        if p is not None:
            return p
        if isinstance(obj, dict):
            for v in obj.values():
                p = find_first_pair(v)
                if p is not None:
                    return p
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                p = find_first_pair(v)
                if p is not None:
                    return p
        return None

    def get_pos(obs):
