        p = find_first_pair(obs)
        return p if p is not None else [0, 0]

    def extract_pairs(obj):
        out = []
        if isinstance(obj, dict):
            p = to_pair(obj)
            if p is not None:
                out.append(p)
            for v in obj.values():
                out.extend(extract_pairs(v))
        elif isinstance(obj, (list, tuple)):
            p = to_pair(obj)
            if p is not None:
                out.append(p)
            else:
                for v in obj:
                    out.extend(extract_pairs(v))
        return out

    def uniq_pairs(ps):
        seen = set()
        out = []
        for p in ps:
            t = (p[0], p[1])
            if t not in seen:
                seen.add(t)
                out.append(p)
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    obs = observation if isinstance(observation, dict) else {}
    pos = get_pos(obs)

    targets = []
